INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$4bed4658$SATQ$, $SATQ$849def3d-1c3e-4354-aa94-6f2485ef2224$SATQ$::uuid, $SATQ$2f18c998-088e-4824-85a2-bd70d1df6b2e$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>In order to prevent nonnative fish species from moving freely between the Mediterranean and Red Seas, marine biologist Bella Galil has proposed that a saline lock system be installed along the Suez Canal in Egypt&rsquo;s Great Bitter Lakes. The lock would increase the salinity of the lakes and <span aria-hidden="true">______</span><span class="sr-only">blank</span> a natural barrier of water most marine creatures would be unable to cross.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"cdda7b6d-accd-4ed4-a178-b6167b49f2ea","content":"<p>creates</p>"},{"id":"8c954e86-ac38-45e1-9906-b4496079375d","content":"<p>create</p>"},{"id":"8fcfeffa-85bd-4a51-a3e0-1b459df04ded","content":"<p>creating</p>"},{"id":"a55be6e5-416f-4cbe-9165-87edc427a709","content":"<p>created</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["8c954e86-ac38-45e1-9906-b4496079375d"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is the use of non-finite (untensed) verb forms in a sentence. The modal &ldquo;would,&rdquo; which indicates the future from a perspective in the past, should be accompanied by a non-finite plain form verb. In this choice, the non-finite plain form verb &ldquo;create&rdquo; is used correctly in conjunction with the non-finite plain form verb &ldquo;increase&rdquo; to describe what the lock would do.
&nbsp;</p><p>Choice A is incorrect because&nbsp;the finite present tense verb &ldquo;creates&rdquo; can&rsquo;t be used in this way with the modal &ldquo;would&rdquo; to describe what the lock would do. Choice C is incorrect because&nbsp;the present participle &ldquo;creating&rdquo; can&rsquo;t be used in this way with the modal &ldquo;would&rdquo; to describe what the lock would do. Choice D is incorrect because the finite past tense verb &ldquo;created&rdquo; can&rsquo;t be used in this way with the modal &ldquo;would&rdquo; to describe what the lock would do. </p>$SATQ$, false, 0, $SATQ$OSP-627-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$8f0a93f6-4fc4-426f-8729-4600c7175d85$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"4bed4658","external_id":"849def3d-1c3e-4354-aa94-6f2485ef2224","vaultid":"2f18c998-088e-4824-85a2-bd70d1df6b2e","uId":"51d67dfb-7bd6-4bbb-86c8-240854dd1dfa","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>In order to prevent nonnative fish species from moving freely between the Mediterranean and Red Seas, marine biologist Bella Galil has proposed that a saline lock system be installed along the Suez Canal in Egypt&rsquo;s Great Bitter Lakes. The lock would increase the salinity of the lakes and <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> a natural barrier of water most marine creatures would be unable to cross.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"cdda7b6d-accd-4ed4-a178-b6167b49f2ea","content":"<p>creates</p>"},{"id":"8c954e86-ac38-45e1-9906-b4496079375d","content":"<p>create</p>"},{"id":"8fcfeffa-85bd-4a51-a3e0-1b459df04ded","content":"<p>creating</p>"},{"id":"a55be6e5-416f-4cbe-9165-87edc427a709","content":"<p>created</p>"}],"keys":["8c954e86-ac38-45e1-9906-b4496079375d"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is the use of non-finite (untensed) verb forms in a sentence. The modal &ldquo;would,&rdquo; which indicates the future from a perspective in the past, should be accompanied by a non-finite plain form verb. In this choice, the non-finite plain form verb &ldquo;create&rdquo; is used correctly in conjunction with the non-finite plain form verb &ldquo;increase&rdquo; to describe what the lock would do.\n&nbsp;</p><p>Choice A is incorrect because&nbsp;the finite present tense verb &ldquo;creates&rdquo; can&rsquo;t be used in this way with the modal &ldquo;would&rdquo; to describe what the lock would do. Choice C is incorrect because&nbsp;the present participle &ldquo;creating&rdquo; can&rsquo;t be used in this way with the modal &ldquo;would&rdquo; to describe what the lock would do. Choice D is incorrect because the finite past tense verb &ldquo;created&rdquo; can&rsquo;t be used in this way with the modal &ldquo;would&rdquo; to describe what the lock would do. </p>","parenttemplatename":"OSP-627-SEC","parenttemplateid":"","templateclusterid":"8f0a93f6-4fc4-426f-8729-4600c7175d85","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959339,"updateDate":1691007959339}$SATQ$::jsonb, 1691007959339, 1691007959339),
    ($SATQ$4c06427b$SATQ$, $SATQ$55a50719-bfd8-4a72-9dca-7309481492bb$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Interest in mechanotransduction, the mechanism by which cells sense and convert mechanical stimuli into biochemical signals, is expanding because of innovative work by biomedical scientists&mdash;many of whom, like neuroscience and biophysics expert Elba Serrano, <span aria-hidden="true">______</span><span class="sr-only">blank</span> this mechanism to better understand how the body&rsquo;s neurological and biomechanical systems interact.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"2405f8f3-de3d-45db-8467-1e640afb1e01","content":"<p>is studying</p>"},{"id":"567e42d1-db69-48c4-a07e-c9932977687f","content":"<p>has studied</p>"},{"id":"a79563b4-7c6e-484c-ba8b-a9fdf0396060","content":"<p>study</p>"},{"id":"39eb0ed0-abbd-4fb4-86d7-78e2914ce4bb","content":"<p>studies</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["a79563b4-7c6e-484c-ba8b-a9fdf0396060"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is the use of verb forms within a sentence. The plural verb "study" agrees in number with the plural subject "many."</p><p>Choice A is incorrect because the singular verb "is studying" doesn&rsquo;t agree in number with the plural subject "many." Choice B is incorrect because the singular verb "has studied" doesn&rsquo;t agree in number with the plural subject "many." Choice D is incorrect because the singular verb "studies" doesn&rsquo;t agree in number with the plural subject "many."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"4c06427b","external_id":"55a50719-bfd8-4a72-9dca-7309481492bb","vaultid":null,"uId":"f10c7358-e569-4c16-99db-cde8200c24c9","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Interest in mechanotransduction, the mechanism by which cells sense and convert mechanical stimuli into biochemical signals, is expanding because of innovative work by biomedical scientists&mdash;many of whom, like neuroscience and biophysics expert Elba Serrano, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> this mechanism to better understand how the body&rsquo;s neurological and biomechanical systems interact.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"2405f8f3-de3d-45db-8467-1e640afb1e01","content":"<p>is studying</p>"},{"id":"567e42d1-db69-48c4-a07e-c9932977687f","content":"<p>has studied</p>"},{"id":"a79563b4-7c6e-484c-ba8b-a9fdf0396060","content":"<p>study</p>"},{"id":"39eb0ed0-abbd-4fb4-86d7-78e2914ce4bb","content":"<p>studies</p>"}],"keys":["a79563b4-7c6e-484c-ba8b-a9fdf0396060"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is the use of verb forms within a sentence. The plural verb \"study\" agrees in number with the plural subject \"many.\"</p><p>Choice A is incorrect because the singular verb \"is studying\" doesn&rsquo;t agree in number with the plural subject \"many.\" Choice B is incorrect because the singular verb \"has studied\" doesn&rsquo;t agree in number with the plural subject \"many.\" Choice D is incorrect because the singular verb \"studies\" doesn&rsquo;t agree in number with the plural subject \"many.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669207,"updateDate":1743430669207}$SATQ$::jsonb, 1743430669207, 1743430669207),
    ($SATQ$4c335aea$SATQ$, $SATQ$7f3c6e0f-f874-4a74-90fc-9094b0b81b29$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>In a recent analysis of lyrical trends in 350,000 songs, researchers cite increases in certain measures, such as the ratio of choruses to verses, as evidence music lyrics are becoming more repetitive. For instance, from 1970 to <span data-ssml-say-as="date">2020</span>, <span aria-hidden="true">______</span><span class="sr-only">blank</span> chorus-to-verse ratios trended similarly, with each genre&rsquo;s data indicating that relative to the number of unique verses, the number of repeated choruses in songs increased. &nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"0f4251b4-0577-42d4-9793-6b70daeae66a","content":"<p>rocks and raps</p>"},{"id":"72147fd9-b2e5-4048-9325-74556445121d","content":"<p>rock&rsquo;s and rap&rsquo;s</p>"},{"id":"8c8d3c2f-8d64-4138-ad21-ba70b2519b79","content":"<p>rocks and rap&rsquo;s</p>"},{"id":"24e1b3b7-b9be-483d-bb56-28cb0596ea4e","content":"<p>rock and rap&rsquo;s</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["72147fd9-b2e5-4048-9325-74556445121d"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is the use of possessive nouns. The singular possessive nouns "rock&rsquo;s" and "rap&rsquo;s" correctly indicate that the chorus-to-verse ratios belong to the genres of rock and rap.</p><p>Choice A is incorrect because the context requires the singular possessive nouns "rock&rsquo;s" and "rap&rsquo;s," not the plural nouns "rocks" and "raps." Choice C is incorrect because the context requires the singular possessive noun "rock&rsquo;s," not the plural noun "rocks." Choice D is incorrect because the context requires the singular possessive noun "rock&rsquo;s," not the singular noun "rock." This choice incorrectly suggests that there was a single chorus-to-verse ratio for rock and rap together, whereas the ratio was calculated for each genre individually.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"4c335aea","external_id":"7f3c6e0f-f874-4a74-90fc-9094b0b81b29","vaultid":null,"uId":"0fe7bef2-4ecc-4178-93a9-f7532648674b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>In a recent analysis of lyrical trends in 350,000 songs, researchers cite increases in certain measures, such as the ratio of choruses to verses, as evidence music lyrics are becoming more repetitive. For instance, from 1970 to <span data-ssml-say-as=\"date\">2020</span>, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> chorus-to-verse ratios trended similarly, with each genre&rsquo;s data indicating that relative to the number of unique verses, the number of repeated choruses in songs increased. &nbsp;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"0f4251b4-0577-42d4-9793-6b70daeae66a","content":"<p>rocks and raps</p>"},{"id":"72147fd9-b2e5-4048-9325-74556445121d","content":"<p>rock&rsquo;s and rap&rsquo;s</p>"},{"id":"8c8d3c2f-8d64-4138-ad21-ba70b2519b79","content":"<p>rocks and rap&rsquo;s</p>"},{"id":"24e1b3b7-b9be-483d-bb56-28cb0596ea4e","content":"<p>rock and rap&rsquo;s</p>"}],"keys":["72147fd9-b2e5-4048-9325-74556445121d"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is the use of possessive nouns. The singular possessive nouns \"rock&rsquo;s\" and \"rap&rsquo;s\" correctly indicate that the chorus-to-verse ratios belong to the genres of rock and rap.</p><p>Choice A is incorrect because the context requires the singular possessive nouns \"rock&rsquo;s\" and \"rap&rsquo;s,\" not the plural nouns \"rocks\" and \"raps.\" Choice C is incorrect because the context requires the singular possessive noun \"rock&rsquo;s,\" not the plural noun \"rocks.\" Choice D is incorrect because the context requires the singular possessive noun \"rock&rsquo;s,\" not the singular noun \"rock.\" This choice incorrectly suggests that there was a single chorus-to-verse ratio for rock and rap together, whereas the ratio was calculated for each genre individually.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061179,"updateDate":1755117061179}$SATQ$::jsonb, 1755117061179, 1755117061179),
    ($SATQ$4c9a2aee$SATQ$, $SATQ$c18288eb-c098-4079-87a7-b154aed1e680$SATQ$::uuid, $SATQ$ccfc734d-f201-4652-aee8-b236cff34029$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>Wanda Diaz-Merced is an astrophysicist who lost her sight when she was young. Diaz-Merced&rsquo;s condition inspired her to develop software that can translate scientific data into sound. Sound-based tools <span aria-hidden="true">______</span><span class="sr-only">blank</span> scientists to detect subtle patterns in data. Such patterns may not be evident in traditional graphs.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"45476120-2224-49b3-9dc2-812f40bf1219","content":"<p>has enabled</p>"},{"id":"363e8a49-05cc-4d55-a762-fb06a0ea8375","content":"<p>enable</p>"},{"id":"d66ea55f-65c1-4e36-a7ab-1789b2ffdde0","content":"<p>is enabling&nbsp;&nbsp;</p>"},{"id":"671e8bc1-d397-43d8-ac83-9a287327645d","content":"<p>enables</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["363e8a49-05cc-4d55-a762-fb06a0ea8375"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is subject-verb agreement. The plural verb "enable" agrees in number with the plural subject "sound-based tools."</p><p>Choice A is incorrect because the singular verb "has enabled" doesn&rsquo;t agree in number with the plural subject "sound-based tools." Choice C is incorrect because the singular verb "is enabling" doesn&rsquo;t agree in number with the plural subject "sound-based tools." Choice D is incorrect because the singular verb "enables" doesn&rsquo;t agree in number with the plural subject "sound-based tools."</p>$SATQ$, false, 0, $SATQ$OSP-KA-FSS-E001$SATQ$, $SATQ$$SATQ$, $SATQ$cc79ac31-256f-4720-8894-c9bc01492e23$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"4c9a2aee","external_id":"c18288eb-c098-4079-87a7-b154aed1e680","vaultid":"ccfc734d-f201-4652-aee8-b236cff34029","uId":"c3fd9c1e-5122-489d-86f6-58a4f8b3f8c6","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>Wanda Diaz-Merced is an astrophysicist who lost her sight when she was young. Diaz-Merced&rsquo;s condition inspired her to develop software that can translate scientific data into sound. Sound-based tools <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> scientists to detect subtle patterns in data. Such patterns may not be evident in traditional graphs.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"45476120-2224-49b3-9dc2-812f40bf1219","content":"<p>has enabled</p>"},{"id":"363e8a49-05cc-4d55-a762-fb06a0ea8375","content":"<p>enable</p>"},{"id":"d66ea55f-65c1-4e36-a7ab-1789b2ffdde0","content":"<p>is enabling&nbsp;&nbsp;</p>"},{"id":"671e8bc1-d397-43d8-ac83-9a287327645d","content":"<p>enables</p>"}],"keys":["363e8a49-05cc-4d55-a762-fb06a0ea8375"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is subject-verb agreement. The plural verb \"enable\" agrees in number with the plural subject \"sound-based tools.\"</p><p>Choice A is incorrect because the singular verb \"has enabled\" doesn&rsquo;t agree in number with the plural subject \"sound-based tools.\" Choice C is incorrect because the singular verb \"is enabling\" doesn&rsquo;t agree in number with the plural subject \"sound-based tools.\" Choice D is incorrect because the singular verb \"enables\" doesn&rsquo;t agree in number with the plural subject \"sound-based tools.\"</p>","parenttemplatename":"OSP-KA-FSS-E001","parenttemplateid":"","templateclusterid":"cc79ac31-256f-4720-8894-c9bc01492e23","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959366,"updateDate":1691007959366}$SATQ$::jsonb, 1691007959366, 1691007959366),
    ($SATQ$4dcedc31$SATQ$, $SATQ$2b2c783d-0fb5-4589-bfab-c94cee0c2768$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>For scientists to produce new iron nanoparticles of a specific size or strength, they must first be able to monitor reactions between oxygen and existing iron nanoparticles at a near-atomic level of detail. Fortunately, chemistry <span aria-hidden="true">______</span><span class="sr-only">blank</span> and his colleagues at Temple University recently developed a new approach that does just that.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"577b43af-06a5-4194-bc5b-f15d101b9858","content":"<p>professor Yugang Sun</p>"},{"id":"60358e1d-1870-41ba-bd59-c9704c152d7b","content":"<p>professor Yugang Sun<span data-ssml-say-as=\"characters\">,</span></p>"},{"id":"faa08d95-2b3d-4ca3-a3a1-2c5687968999","content":"<p>professor<span data-ssml-say-as=\"characters\">,</span> Yugang Sun<span data-ssml-say-as=\"characters\">,</span></p>"},{"id":"2a0567f7-b1b9-4c4c-abe4-9c41095b7fe4","content":"<p>professor<span data-ssml-say-as=\"characters\">,</span> Yugang Sun</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["577b43af-06a5-4194-bc5b-f15d101b9858"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the use of punctuation between titles and proper nouns. No punctuation is needed between the proper noun &ldquo;Yugang Sun&rdquo; and the title that describes Sun, &ldquo;chemistry professor.&rdquo; Furthermore, no punctuation is needed after &ldquo;Sun&rdquo; because &ldquo;chemistry professor Yugang Sun and his colleagues at Temple University&rdquo; functions as the coordinated subject of the sentence, and together Sun and colleagues performed the action of developing a new approach to producing iron nanoparticles.</p><p>Choice B is incorrect because no punctuation is needed between the proper noun &ldquo;Yugang Sun&rdquo; and the coordinated noun phrase &ldquo;and his colleagues at Temple University.&rdquo; Choice C is incorrect because no punctuation is needed before or after the proper noun &ldquo;Yugang Sun.&rdquo; Setting off the professor&rsquo;s name with commas suggests that it could be removed without affecting the coherence of the sentence, which isn&rsquo;t the case. Choice D is incorrect because no punctuation is needed between the title &ldquo;chemistry professor&rdquo; and the proper noun &ldquo;Yugang Sun.&rdquo;</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"4dcedc31","external_id":"2b2c783d-0fb5-4589-bfab-c94cee0c2768","vaultid":null,"uId":"23acac8b-b640-4ec8-932b-3fb9a07d7f53","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>For scientists to produce new iron nanoparticles of a specific size or strength, they must first be able to monitor reactions between oxygen and existing iron nanoparticles at a near-atomic level of detail. Fortunately, chemistry <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> and his colleagues at Temple University recently developed a new approach that does just that.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"577b43af-06a5-4194-bc5b-f15d101b9858","content":"<p>professor Yugang Sun</p>"},{"id":"60358e1d-1870-41ba-bd59-c9704c152d7b","content":"<p>professor Yugang Sun<span data-ssml-say-as=\"characters\">,</span></p>"},{"id":"faa08d95-2b3d-4ca3-a3a1-2c5687968999","content":"<p>professor<span data-ssml-say-as=\"characters\">,</span> Yugang Sun<span data-ssml-say-as=\"characters\">,</span></p>"},{"id":"2a0567f7-b1b9-4c4c-abe4-9c41095b7fe4","content":"<p>professor<span data-ssml-say-as=\"characters\">,</span> Yugang Sun</p>"}],"keys":["577b43af-06a5-4194-bc5b-f15d101b9858"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is the use of punctuation between titles and proper nouns. No punctuation is needed between the proper noun &ldquo;Yugang Sun&rdquo; and the title that describes Sun, &ldquo;chemistry professor.&rdquo; Furthermore, no punctuation is needed after &ldquo;Sun&rdquo; because &ldquo;chemistry professor Yugang Sun and his colleagues at Temple University&rdquo; functions as the coordinated subject of the sentence, and together Sun and colleagues performed the action of developing a new approach to producing iron nanoparticles.</p><p>Choice B is incorrect because no punctuation is needed between the proper noun &ldquo;Yugang Sun&rdquo; and the coordinated noun phrase &ldquo;and his colleagues at Temple University.&rdquo; Choice C is incorrect because no punctuation is needed before or after the proper noun &ldquo;Yugang Sun.&rdquo; Setting off the professor&rsquo;s name with commas suggests that it could be removed without affecting the coherence of the sentence, which isn&rsquo;t the case. Choice D is incorrect because no punctuation is needed between the title &ldquo;chemistry professor&rdquo; and the proper noun &ldquo;Yugang Sun.&rdquo;</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771168,"updateDate":1776362771168}$SATQ$::jsonb, 1776362771168, 1776362771168),
    ($SATQ$4f2ff5f2$SATQ$, $SATQ$38edd1af-9ea5-446b-954a-aa2b3dde22d2$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Tortoises can be found in many works of literature. For example, in Tom Stoppard&rsquo;s 1993 play <em>Arcadia</em>, there is a tortoise that <span aria-hidden="true">______</span><span class="sr-only">blank</span> by two names (Plautus and Lightning) and appears in both of the play&rsquo;s parallel timelines. As a character, the tortoise symbolizes the connection between the past and present.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"5106bc62-25a8-4772-b485-4c017c66a48d","content":"<p>goes</p>"},{"id":"70a17d49-bc12-4674-9b8a-6b0b72a85fe1","content":"<p>will have gone</p>"},{"id":"1d6ec868-fc67-4305-a727-59ac62756de0","content":"<p>went</p>"},{"id":"7da23ddc-4095-4a5f-b601-2dc0de046be6","content":"<p>had gone</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["5106bc62-25a8-4772-b485-4c017c66a48d"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the use of verbs to express tense in a sentence. In this choice, the present tense verb "goes" is consistent with the other present tense verbs ("appears" and "symbolizes") used to describe the tortoise in Stoppard&rsquo;s play. Furthermore, it&rsquo;s conventional to use the present tense when discussing a literary work.</p><p>Choice B is incorrect because the future perfect tense verb "will have gone" isn&rsquo;t consistent with the other present tense verbs used to describe the tortoise in Stoppard&rsquo;s play. Choice C is incorrect because the past tense verb "went" isn&rsquo;t consistent with the other present tense verbs used to describe the tortoise in Stoppard&rsquo;s play. Choice D is incorrect because the past perfect tense verb "had gone" isn&rsquo;t consistent with the other present tense verbs used to describe the tortoise in Stoppard&rsquo;s play.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"4f2ff5f2","external_id":"38edd1af-9ea5-446b-954a-aa2b3dde22d2","vaultid":null,"uId":"5fb856a4-bdb2-4e3e-b536-88c380155b05","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Tortoises can be found in many works of literature. For example, in Tom Stoppard&rsquo;s 1993 play <em>Arcadia</em>, there is a tortoise that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> by two names (Plautus and Lightning) and appears in both of the play&rsquo;s parallel timelines. As a character, the tortoise symbolizes the connection between the past and present.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"5106bc62-25a8-4772-b485-4c017c66a48d","content":"<p>goes</p>"},{"id":"70a17d49-bc12-4674-9b8a-6b0b72a85fe1","content":"<p>will have gone</p>"},{"id":"1d6ec868-fc67-4305-a727-59ac62756de0","content":"<p>went</p>"},{"id":"7da23ddc-4095-4a5f-b601-2dc0de046be6","content":"<p>had gone</p>"}],"keys":["5106bc62-25a8-4772-b485-4c017c66a48d"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is the use of verbs to express tense in a sentence. In this choice, the present tense verb \"goes\" is consistent with the other present tense verbs (\"appears\" and \"symbolizes\") used to describe the tortoise in Stoppard&rsquo;s play. Furthermore, it&rsquo;s conventional to use the present tense when discussing a literary work.</p><p>Choice B is incorrect because the future perfect tense verb \"will have gone\" isn&rsquo;t consistent with the other present tense verbs used to describe the tortoise in Stoppard&rsquo;s play. Choice C is incorrect because the past tense verb \"went\" isn&rsquo;t consistent with the other present tense verbs used to describe the tortoise in Stoppard&rsquo;s play. Choice D is incorrect because the past perfect tense verb \"had gone\" isn&rsquo;t consistent with the other present tense verbs used to describe the tortoise in Stoppard&rsquo;s play.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323051,"updateDate":1730147323051}$SATQ$::jsonb, 1730147323051, 1730147323051),
    ($SATQ$50445680$SATQ$, $SATQ$75a68c82-90ac-4a3e-82e7-d428173a67c8$SATQ$::uuid, $SATQ$3183055f-32ba-4f9d-9964-7653e609ad74$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>In winter, the diets of Japanese macaques, also known as snow monkeys, are influenced more by food availability than by food preference. Although the monkeys prefer to eat vegetation and land-dwelling invertebrates, those food sources may become unavailable because of extensive snow and ice cover, <span aria-hidden="true">______</span><span class="sr-only">blank</span> the monkeys to hunt for marine animals in any streams that have not frozen over.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"ec1f663b-65b7-4d85-b094-71fffd109f32","content":"<p>forces</p>"},{"id":"72eec95b-a42c-4b13-a1b7-09acc27b61af","content":"<p>to force</p>"},{"id":"aede1895-f66c-4a09-9330-f26a55e4cc0c","content":"<p>forcing</p>"},{"id":"7dac44da-55d4-4fde-b18b-73df65310cb2","content":"<p>forced</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["aede1895-f66c-4a09-9330-f26a55e4cc0c"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is the use of finite and nonfinite verb forms within a sentence. The nonfinite present participle &ldquo;forcing&rdquo; is correctly used to form a participial phrase that supplements the main clause &ldquo;those...cover,&rdquo; describing the effects on monkeys of the lack of food sources. </p><p>Choice A is incorrect because the finite present tense verb &ldquo;forces&rdquo; can&rsquo;t be used in this way to supplement the main clause (&ldquo;those...cover&rdquo;). Choice B is incorrect. While the nonfinite to-infinitive &ldquo;to force&rdquo; could be used to form a subordinate clause that supplements the main clause (&ldquo;those...cover&rdquo;), to-infinitives conventionally express purpose, and nothing in the sentence suggests that the food sources become unavailable for the purpose of forcing monkeys to hunt marine animals. Choice D is incorrect because the finite past tense verb &ldquo;forced&rdquo; can&rsquo;t be used in this way to supplement the main clause (&ldquo;those...cover&rdquo;). </p>$SATQ$, false, 0, $SATQ$OSP-687-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$55a96e52-98b9-4387-9d93-b1fb6aaa2629$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"50445680","external_id":"75a68c82-90ac-4a3e-82e7-d428173a67c8","vaultid":"3183055f-32ba-4f9d-9964-7653e609ad74","uId":"82844ecd-e541-4c6e-a467-17f1c0c9feec","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>In winter, the diets of Japanese macaques, also known as snow monkeys, are influenced more by food availability than by food preference. Although the monkeys prefer to eat vegetation and land-dwelling invertebrates, those food sources may become unavailable because of extensive snow and ice cover, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the monkeys to hunt for marine animals in any streams that have not frozen over.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"ec1f663b-65b7-4d85-b094-71fffd109f32","content":"<p>forces</p>"},{"id":"72eec95b-a42c-4b13-a1b7-09acc27b61af","content":"<p>to force</p>"},{"id":"aede1895-f66c-4a09-9330-f26a55e4cc0c","content":"<p>forcing</p>"},{"id":"7dac44da-55d4-4fde-b18b-73df65310cb2","content":"<p>forced</p>"}],"keys":["aede1895-f66c-4a09-9330-f26a55e4cc0c"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is the use of finite and nonfinite verb forms within a sentence. The nonfinite present participle &ldquo;forcing&rdquo; is correctly used to form a participial phrase that supplements the main clause &ldquo;those...cover,&rdquo; describing the effects on monkeys of the lack of food sources. </p><p>Choice A is incorrect because the finite present tense verb &ldquo;forces&rdquo; can&rsquo;t be used in this way to supplement the main clause (&ldquo;those...cover&rdquo;). Choice B is incorrect. While the nonfinite to-infinitive &ldquo;to force&rdquo; could be used to form a subordinate clause that supplements the main clause (&ldquo;those...cover&rdquo;), to-infinitives conventionally express purpose, and nothing in the sentence suggests that the food sources become unavailable for the purpose of forcing monkeys to hunt marine animals. Choice D is incorrect because the finite past tense verb &ldquo;forced&rdquo; can&rsquo;t be used in this way to supplement the main clause (&ldquo;those...cover&rdquo;). </p>","parenttemplatename":"OSP-687-SEC","parenttemplateid":"","templateclusterid":"55a96e52-98b9-4387-9d93-b1fb6aaa2629","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959346,"updateDate":1691007959346}$SATQ$::jsonb, 1691007959346, 1691007959346),
    ($SATQ$50801257$SATQ$, $SATQ$66e7598c-d405-4449-acce-7ae859d2c9f5$SATQ$::uuid, $SATQ$a3376fa1-27fb-443d-a8d8-215513f5fbdf$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>In 1994, almost 200 years after the death of Wang Zhenyi, the International Astronomical <span aria-hidden="true">______</span><span class="sr-only">blank</span> the contributions of the barrier-breaking 18th-century astronomer and author of &ldquo;Dispute of the Procession of the Equinoxes,&rdquo; naming a crater on Venus after her.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"950dbf32-0237-49e1-9131-0db41f1e5a18","content":"<p>Union would finally acknowledge</p>"},{"id":"041ba098-3d6e-4cd3-82c3-097dfc4b1f08","content":"<p>Union to finally acknowledge</p>"},{"id":"32793eff-3e23-4643-b7a5-b5ceee042ee0","content":"<p>Union, having finally acknowledged</p>"},{"id":"e195e684-2ab4-4534-a4ff-1bcb29f13040","content":"<p>Union, finally acknowledging</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["950dbf32-0237-49e1-9131-0db41f1e5a18"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. It&rsquo;s the only choice that offers a form of the verb &ldquo;acknowledge&rdquo; that can go with the subject &ldquo;International Astronomical Union&rdquo; to make a complete sentence. This might seem like an odd use of &ldquo;would,&rdquo; but when speaking from a point of view in the past, we can actually use &ldquo;would&rdquo; to express something that happened later. That&rsquo;s the case here: 200 years after Wang Zhenyi&rsquo;s death, the IAU would finally acknowledge her contributions. </p><p>Choice B is incorrect. This choice creates a sentence fragment. There&rsquo;s no main verb elsewhere in the sentence, so we need a form of the verb &ldquo;acknowledge&rdquo; that can go with the subject &ldquo;the International Astronomical Union&rdquo; and serve as that main verb. &ldquo;To acknowledge&rdquo; can&rsquo;t do that. Choice C is incorrect. This choice creates a sentence fragment. There&rsquo;s no main verb elsewhere in the sentence, so we need a form of the verb &ldquo;acknowledge&rdquo; that can go with the subject &ldquo;the International Astronomical Union&rdquo; and serve as that main verb. &ldquo;Having acknowledged&rdquo; can&rsquo;t do that. Choice D is incorrect. This choice creates a sentence fragment. There&rsquo;s no main verb elsewhere in the sentence, so we need a form of the verb &ldquo;acknowledge&rdquo; that can go with the subject &ldquo;the International Astronomical Union&rdquo; and serve as that main verb. The &ldquo;-ing&rdquo; form can&rsquo;t do that. </p>$SATQ$, false, 0, $SATQ$OSP-KA-FSS-H003$SATQ$, $SATQ$$SATQ$, $SATQ$32cf962b-f59d-4a05-b277-2351e37731ef$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"50801257","external_id":"66e7598c-d405-4449-acce-7ae859d2c9f5","vaultid":"a3376fa1-27fb-443d-a8d8-215513f5fbdf","uId":"cecff274-a3c4-46bb-a2e6-568d49cdb340","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>In 1994, almost 200 years after the death of Wang Zhenyi, the International Astronomical <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the contributions of the barrier-breaking 18th-century astronomer and author of &ldquo;Dispute of the Procession of the Equinoxes,&rdquo; naming a crater on Venus after her.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"950dbf32-0237-49e1-9131-0db41f1e5a18","content":"<p>Union would finally acknowledge</p>"},{"id":"041ba098-3d6e-4cd3-82c3-097dfc4b1f08","content":"<p>Union to finally acknowledge</p>"},{"id":"32793eff-3e23-4643-b7a5-b5ceee042ee0","content":"<p>Union, having finally acknowledged</p>"},{"id":"e195e684-2ab4-4534-a4ff-1bcb29f13040","content":"<p>Union, finally acknowledging</p>"}],"keys":["950dbf32-0237-49e1-9131-0db41f1e5a18"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. It&rsquo;s the only choice that offers a form of the verb &ldquo;acknowledge&rdquo; that can go with the subject &ldquo;International Astronomical Union&rdquo; to make a complete sentence. This might seem like an odd use of &ldquo;would,&rdquo; but when speaking from a point of view in the past, we can actually use &ldquo;would&rdquo; to express something that happened later. That&rsquo;s the case here: 200 years after Wang Zhenyi&rsquo;s death, the IAU would finally acknowledge her contributions. </p><p>Choice B is incorrect. This choice creates a sentence fragment. There&rsquo;s no main verb elsewhere in the sentence, so we need a form of the verb &ldquo;acknowledge&rdquo; that can go with the subject &ldquo;the International Astronomical Union&rdquo; and serve as that main verb. &ldquo;To acknowledge&rdquo; can&rsquo;t do that. Choice C is incorrect. This choice creates a sentence fragment. There&rsquo;s no main verb elsewhere in the sentence, so we need a form of the verb &ldquo;acknowledge&rdquo; that can go with the subject &ldquo;the International Astronomical Union&rdquo; and serve as that main verb. &ldquo;Having acknowledged&rdquo; can&rsquo;t do that. Choice D is incorrect. This choice creates a sentence fragment. There&rsquo;s no main verb elsewhere in the sentence, so we need a form of the verb &ldquo;acknowledge&rdquo; that can go with the subject &ldquo;the International Astronomical Union&rdquo; and serve as that main verb. The &ldquo;-ing&rdquo; form can&rsquo;t do that. </p>","parenttemplatename":"OSP-KA-FSS-H003","parenttemplateid":"","templateclusterid":"32cf962b-f59d-4a05-b277-2351e37731ef","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959367,"updateDate":1691007959367}$SATQ$::jsonb, 1691007959367, 1691007959367),
    ($SATQ$512f0ac9$SATQ$, $SATQ$d17935b6-fc0c-4512-97c0-74e5f85706b2$SATQ$::uuid, $SATQ$cbb65aea-a70c-4a8c-9c3d-a81bebafe9a9$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Working from an earlier discovery of Charpentier&rsquo;s, chemists Emmanuelle Charpentier and Jennifer Doudna&mdash;winners of the 2020 Nobel Prize in Chemistry&mdash;re-created and then reprogrammed the so-called &ldquo;genetic scissors&rdquo; of a species of DNA-cleaving bacteria <span aria-hidden="true">______</span><span class="sr-only">blank</span> a tool that is revolutionizing the field of gene technology.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"80796094-ec4e-4816-824a-ac49d98fad77","content":"<p>to forge</p>"},{"id":"41707ed0-1b35-47fa-8138-74f173a2a26b","content":"<p>forging</p>"},{"id":"3e7fb366-9834-4958-afe3-2f516fde55f3","content":"<p>forged</p>"},{"id":"b8252c14-cc15-4c96-b312-722d103273b6","content":"<p>and forging</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["80796094-ec4e-4816-824a-ac49d98fad77"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the use of finite and nonfinite verb forms within a sentence. The nonfinite to-infinitive &ldquo;to forge&rdquo; is correctly used to form a nonfinite (infinitive) clause that explains why the chemists re-created and reprogrammed the DNA-cleaving bacteria. </p><p>Choice B is incorrect. Without a comma separating the main clause (&ldquo;chemists...bacteria&rdquo;) from the participle &ldquo;forging,&rdquo; this choice illogically suggests that the bacteria are forging a tool, which doesn&rsquo;t make sense. Choice C is incorrect. Without a coordinating conjunction such as &ldquo;and&rdquo; placed before it, the finite past tense verb &ldquo;forged&rdquo; can&rsquo;t be used in this way to describe the chemists&rsquo; actions. Choice D is incorrect. If read as a finite verb, the present progressive verb &ldquo;forging&rdquo; isn&rsquo;t consistent with the past tense verbs used in this sentence to describe the actions of the chemists. If read as a nonfinite verb, the participle &ldquo;forging&rdquo; can&rsquo;t be used in this way because there is no following main clause for it to modify.&nbsp;&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-707-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$0ef772fc-ca93-4c5d-98b9-11cdd7b9717c$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"512f0ac9","external_id":"d17935b6-fc0c-4512-97c0-74e5f85706b2","vaultid":"cbb65aea-a70c-4a8c-9c3d-a81bebafe9a9","uId":"375ebd8e-4290-445b-ba46-c95d7816092b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Working from an earlier discovery of Charpentier&rsquo;s, chemists Emmanuelle Charpentier and Jennifer Doudna&mdash;winners of the 2020 Nobel Prize in Chemistry&mdash;re-created and then reprogrammed the so-called &ldquo;genetic scissors&rdquo; of a species of DNA-cleaving bacteria <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> a tool that is revolutionizing the field of gene technology.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"80796094-ec4e-4816-824a-ac49d98fad77","content":"<p>to forge</p>"},{"id":"41707ed0-1b35-47fa-8138-74f173a2a26b","content":"<p>forging</p>"},{"id":"3e7fb366-9834-4958-afe3-2f516fde55f3","content":"<p>forged</p>"},{"id":"b8252c14-cc15-4c96-b312-722d103273b6","content":"<p>and forging</p>"}],"keys":["80796094-ec4e-4816-824a-ac49d98fad77"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is the use of finite and nonfinite verb forms within a sentence. The nonfinite to-infinitive &ldquo;to forge&rdquo; is correctly used to form a nonfinite (infinitive) clause that explains why the chemists re-created and reprogrammed the DNA-cleaving bacteria. </p><p>Choice B is incorrect. Without a comma separating the main clause (&ldquo;chemists...bacteria&rdquo;) from the participle &ldquo;forging,&rdquo; this choice illogically suggests that the bacteria are forging a tool, which doesn&rsquo;t make sense. Choice C is incorrect. Without a coordinating conjunction such as &ldquo;and&rdquo; placed before it, the finite past tense verb &ldquo;forged&rdquo; can&rsquo;t be used in this way to describe the chemists&rsquo; actions. Choice D is incorrect. If read as a finite verb, the present progressive verb &ldquo;forging&rdquo; isn&rsquo;t consistent with the past tense verbs used in this sentence to describe the actions of the chemists. If read as a nonfinite verb, the participle &ldquo;forging&rdquo; can&rsquo;t be used in this way because there is no following main clause for it to modify.&nbsp;&nbsp;</p>","parenttemplatename":"OSP-707-SEC","parenttemplateid":"","templateclusterid":"0ef772fc-ca93-4c5d-98b9-11cdd7b9717c","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959347,"updateDate":1691007959347}$SATQ$::jsonb, 1691007959347, 1691007959347),
    ($SATQ$52b61716$SATQ$, $SATQ$e0bd0d1c-70a9-41c6-91b0-62f15f6fb5eb$SATQ$::uuid, $SATQ$6e10fbea-2c3c-4a11-8c35-8a0ac9fb8c8e$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Formed in 1967 to foster political and economic stability within the Asia-Pacific region, the Association of Southeast Asian Nations was originally made up of five members: Thailand, the Philippines, Singapore, Malaysia, and Indonesia. By the end of the 1990s, the organization <span aria-hidden="true">______</span><span class="sr-only">blank</span> its initial membership.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"2deea374-4a27-4cb6-8bcd-4d933ed39fe1","content":"<p>has doubled</p>"},{"id":"a5a2a9dc-8044-4be6-a243-f2c932979a4b","content":"<p>had doubled</p>"},{"id":"99044188-79c2-4b8f-ad72-e9b86d95df62","content":"<p>doubles</p>"},{"id":"f3e5b9fc-b7b2-4b66-958e-0138ce9fda2b","content":"<p>will double</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["a5a2a9dc-8044-4be6-a243-f2c932979a4b"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is the use of verbs to express tense. In this choice, the past perfect verb &ldquo;had doubled&rdquo; properly indicates that the doubling of the organization&rsquo;s initial membership occurred during a specific period before the present (between the organization&rsquo;s founding in 1967 and the end of the 1990s).&nbsp;</p><p>Choice A is incorrect because the present perfect verb &ldquo;has doubled&rdquo; doesn&rsquo;t indicate that the organization&rsquo;s doubling of its initial membership occurred during a specific period in the past.&nbsp;Choice C is incorrect because the present tense verb &ldquo;doubles&rdquo; doesn&rsquo;t indicate that the organization&rsquo;s doubling of its initial membership occurred during a specific period in the past. Choice D is incorrect because the future tense verb &ldquo;will double&rdquo; doesn&rsquo;t indicate that the organization&rsquo;s doubling of its initial membership occurred during a specific period in the past. </p>$SATQ$, false, 0, $SATQ$OSP-690-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$c62ccbeb-ebf9-4923-90b5-76ba31272a95$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"52b61716","external_id":"e0bd0d1c-70a9-41c6-91b0-62f15f6fb5eb","vaultid":"6e10fbea-2c3c-4a11-8c35-8a0ac9fb8c8e","uId":"1cd537b6-fdd1-4044-b0f5-8440725ea09c","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Formed in 1967 to foster political and economic stability within the Asia-Pacific region, the Association of Southeast Asian Nations was originally made up of five members: Thailand, the Philippines, Singapore, Malaysia, and Indonesia. By the end of the 1990s, the organization <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> its initial membership.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"2deea374-4a27-4cb6-8bcd-4d933ed39fe1","content":"<p>has doubled</p>"},{"id":"a5a2a9dc-8044-4be6-a243-f2c932979a4b","content":"<p>had doubled</p>"},{"id":"99044188-79c2-4b8f-ad72-e9b86d95df62","content":"<p>doubles</p>"},{"id":"f3e5b9fc-b7b2-4b66-958e-0138ce9fda2b","content":"<p>will double</p>"}],"keys":["a5a2a9dc-8044-4be6-a243-f2c932979a4b"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is the use of verbs to express tense. In this choice, the past perfect verb &ldquo;had doubled&rdquo; properly indicates that the doubling of the organization&rsquo;s initial membership occurred during a specific period before the present (between the organization&rsquo;s founding in 1967 and the end of the 1990s).&nbsp;</p><p>Choice A is incorrect because the present perfect verb &ldquo;has doubled&rdquo; doesn&rsquo;t indicate that the organization&rsquo;s doubling of its initial membership occurred during a specific period in the past.&nbsp;Choice C is incorrect because the present tense verb &ldquo;doubles&rdquo; doesn&rsquo;t indicate that the organization&rsquo;s doubling of its initial membership occurred during a specific period in the past. Choice D is incorrect because the future tense verb &ldquo;will double&rdquo; doesn&rsquo;t indicate that the organization&rsquo;s doubling of its initial membership occurred during a specific period in the past. </p>","parenttemplatename":"OSP-690-SEC","parenttemplateid":"","templateclusterid":"c62ccbeb-ebf9-4923-90b5-76ba31272a95","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959346,"updateDate":1691007959346}$SATQ$::jsonb, 1691007959346, 1691007959346),
    ($SATQ$548f4956$SATQ$, $SATQ$e04cdf67-05e6-4aa1-9e20-580977e98de5$SATQ$::uuid, $SATQ$239c173c-e8ad-46db-aaad-0de562cb106d$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>It is generally true that technological change is a linear process, in which once-useful technologies are replaced by new and better <span aria-hidden="true">______</span><span class="sr-only">blank</span> the reawakening of interest in the steam engine (from advocates of carbon-neutral rail travel) reminds us that ostensibly obsolete technologies may be brought back into service to address society&rsquo;s changing needs.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"36996291-81b3-4af1-a190-37f93d86488f","content":"<p>ones, even so;&nbsp;</p>"},{"id":"b61db921-0d81-49c1-b2f9-e5c950cfd402","content":"<p>ones even so,&nbsp;</p>"},{"id":"2da7a0f9-ba3d-4a3c-a311-f732f0d1f5fd","content":"<p>ones; even so,&nbsp;</p>"},{"id":"14100b4c-84fc-4058-ac27-37c0a64db5d5","content":"<p>ones, even so,&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["2da7a0f9-ba3d-4a3c-a311-f732f0d1f5fd"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is the coordination of main clauses within a sentence. This choice uses a semicolon in a conventional way to join the first main clause (&ldquo;It is&hellip;ones&rdquo;) and the second main clause &nbsp;(&ldquo;even so&hellip;needs&rdquo;). Furthermore, the placement of the semicolon after &ldquo;ones&rdquo; indicates that the supplementary phrase &ldquo;even so&rdquo; modifies the following clause (&ldquo;the reawakening...needs&rdquo;), resulting in the most logical and grammatically complete sentence. With this punctuation, the sentence logically indicates that the recent interest in an old technology like steam engines is despite the fact that technological change typically seeks out new technologies. </p><p>Choice A is incorrect because it results in a confusing and illogical sentence. Placing the semicolon after &ldquo;so&rdquo; indicates that the supplementary element &ldquo;even so&rdquo; modifies the first clause of the sentence, which doesn&rsquo;t make sense in this context. Choice B is incorrect because it results in a run-on sentence. It fails to mark the boundary between the two main clauses with appropriate punctuation. Choice D is incorrect because it results in a comma splice. Without a conjunction following it, a comma can&rsquo;t be used in this way to join the two main clauses of the sentence. </p>$SATQ$, false, 0, $SATQ$OSP-792-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$7659bfe6-9ea0-4376-bbd5-4f738b4abd78$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"548f4956","external_id":"e04cdf67-05e6-4aa1-9e20-580977e98de5","vaultid":"239c173c-e8ad-46db-aaad-0de562cb106d","uId":"6c7eb0d2-e210-4c9f-87aa-4d32d5a72622","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>It is generally true that technological change is a linear process, in which once-useful technologies are replaced by new and better <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the reawakening of interest in the steam engine (from advocates of carbon-neutral rail travel) reminds us that ostensibly obsolete technologies may be brought back into service to address society&rsquo;s changing needs.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"36996291-81b3-4af1-a190-37f93d86488f","content":"<p>ones, even so;&nbsp;</p>"},{"id":"b61db921-0d81-49c1-b2f9-e5c950cfd402","content":"<p>ones even so,&nbsp;</p>"},{"id":"2da7a0f9-ba3d-4a3c-a311-f732f0d1f5fd","content":"<p>ones; even so,&nbsp;</p>"},{"id":"14100b4c-84fc-4058-ac27-37c0a64db5d5","content":"<p>ones, even so,&nbsp;</p>"}],"keys":["2da7a0f9-ba3d-4a3c-a311-f732f0d1f5fd"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is the coordination of main clauses within a sentence. This choice uses a semicolon in a conventional way to join the first main clause (&ldquo;It is&hellip;ones&rdquo;) and the second main clause &nbsp;(&ldquo;even so&hellip;needs&rdquo;). Furthermore, the placement of the semicolon after &ldquo;ones&rdquo; indicates that the supplementary phrase &ldquo;even so&rdquo; modifies the following clause (&ldquo;the reawakening...needs&rdquo;), resulting in the most logical and grammatically complete sentence. With this punctuation, the sentence logically indicates that the recent interest in an old technology like steam engines is despite the fact that technological change typically seeks out new technologies. </p><p>Choice A is incorrect because it results in a confusing and illogical sentence. Placing the semicolon after &ldquo;so&rdquo; indicates that the supplementary element &ldquo;even so&rdquo; modifies the first clause of the sentence, which doesn&rsquo;t make sense in this context. Choice B is incorrect because it results in a run-on sentence. It fails to mark the boundary between the two main clauses with appropriate punctuation. Choice D is incorrect because it results in a comma splice. Without a conjunction following it, a comma can&rsquo;t be used in this way to join the two main clauses of the sentence. </p>","parenttemplatename":"OSP-792-SEC","parenttemplateid":"","templateclusterid":"7659bfe6-9ea0-4376-bbd5-4f738b4abd78","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959353,"updateDate":1691007959353}$SATQ$::jsonb, 1691007959353, 1691007959353),
    ($SATQ$56315bd0$SATQ$, $SATQ$01d852b8-1a06-4514-b580-1127a9d57e47$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Solarpunk is an art movement that imagines renewable energy&ndash;powered technology infused complementarily into nature. In Paolo Bacigalupi&rsquo;s solarpunk short story &ldquo;Efficiency,&rdquo; an artificial intelligence that absorbs sustainable energies, redistributing them through intricate networks of weights and generators, <span aria-hidden="true">______</span><span class="sr-only">blank</span> Chicago&rsquo;s energy grid.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"dd404784-e123-4fea-929e-4d9ce5b4c165","content":"<p>have been powering</p>"},{"id":"ed7c1738-388f-4b46-82b2-648e303ad9c2","content":"<p>power</p>"},{"id":"485c8f3b-de6d-4bf2-9b5c-88a7a8f73e33","content":"<p>powers</p>"},{"id":"2c2e4817-1c1c-4383-aacf-99092bc6e9f7","content":"<p>are powering</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["485c8f3b-de6d-4bf2-9b5c-88a7a8f73e33"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is subject-verb agreement. The singular verb "powers" agrees in number with the singular subject "an artificial intelligence."</p><p>Choice A is incorrect because the plural verb "have been powering" doesn&rsquo;t agree in number with the singular subject "an artificial intelligence." Choice B is incorrect because the plural verb "power" doesn&rsquo;t agree in number with the singular subject "an artificial intelligence." Choice D is incorrect because the plural verb "are powering" doesn&rsquo;t agree in number with the singular subject "an artificial intelligence."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"56315bd0","external_id":"01d852b8-1a06-4514-b580-1127a9d57e47","vaultid":null,"uId":"3f3d6ac0-31bd-45de-8489-29fb1e798f3f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Solarpunk is an art movement that imagines renewable energy&ndash;powered technology infused complementarily into nature. In Paolo Bacigalupi&rsquo;s solarpunk short story &ldquo;Efficiency,&rdquo; an artificial intelligence that absorbs sustainable energies, redistributing them through intricate networks of weights and generators, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> Chicago&rsquo;s energy grid.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"dd404784-e123-4fea-929e-4d9ce5b4c165","content":"<p>have been powering</p>"},{"id":"ed7c1738-388f-4b46-82b2-648e303ad9c2","content":"<p>power</p>"},{"id":"485c8f3b-de6d-4bf2-9b5c-88a7a8f73e33","content":"<p>powers</p>"},{"id":"2c2e4817-1c1c-4383-aacf-99092bc6e9f7","content":"<p>are powering</p>"}],"keys":["485c8f3b-de6d-4bf2-9b5c-88a7a8f73e33"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is subject-verb agreement. The singular verb \"powers\" agrees in number with the singular subject \"an artificial intelligence.\"</p><p>Choice A is incorrect because the plural verb \"have been powering\" doesn&rsquo;t agree in number with the singular subject \"an artificial intelligence.\" Choice B is incorrect because the plural verb \"power\" doesn&rsquo;t agree in number with the singular subject \"an artificial intelligence.\" Choice D is incorrect because the plural verb \"are powering\" doesn&rsquo;t agree in number with the singular subject \"an artificial intelligence.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323051,"updateDate":1730147323051}$SATQ$::jsonb, 1730147323051, 1730147323051),
    ($SATQ$5670a657$SATQ$, $SATQ$86d7d04f-3f8f-48a2-8086-f4465af48abb$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>During the decades-long movement to codify the rights of Latinos in the US, certain events were pivotal: the founding of social justice group the League of United Latin American Citizens in <span aria-hidden="true">______</span><span class="sr-only">blank</span> <em>Katzenbach <span data-ssml-sub-alias="v">v.</span> Morgan</em> court decision in <span data-ssml-say-as="date">1966</span>, which affirmed the rights of Latino voters, is another such event.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"cc32da26-85bd-476a-b105-f88fd0bf5edb","content":"<p><span data-ssml-say-as=\"date\">1929</span><span data-ssml-say-as=\"characters\">.</span> For one<span data-ssml-say-as=\"characters\">,</span> the</p>"},{"id":"1e705568-c0a3-4cb7-94a0-d9b555c57c72","content":"<p><span data-ssml-say-as=\"date\">1929</span><span data-ssml-say-as=\"characters\">,</span> for one<span data-ssml-say-as=\"characters\">,</span> the</p>"},{"id":"ffdd0cc6-df04-43d1-bffb-cefd7586a06f","content":"<p><span data-ssml-say-as=\"date\">1929</span> for one<span data-ssml-say-as=\"characters\">,</span> the</p>"},{"id":"47e4e962-4699-4dec-b6de-83961f2a963d","content":"<p><span data-ssml-say-as=\"date\">1929</span><span data-ssml-say-as=\"characters\">,</span> for one<span data-ssml-say-as=\"characters\">.</span> The</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["47e4e962-4699-4dec-b6de-83961f2a963d"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The conventions being tested are punctuation use between sentences and the punctuation of a supplementary element. This choice correctly uses a period to mark the boundary between one sentence ("During...one") and another ("The <em>Katzenbach</em>...event") and uses a comma to separate the supplementary phrase "for one" from the preceding main clause. Further, placing the period after "for one" correctly indicates that the information in the preceding main clause ("the founding...1929") is the first example provided of a pivotal event in the Latino rights movement.</p><p>Choice A is incorrect because placing the period after "1929" illogically indicates that the information in the next main clause (describing the <em>Katzenbach v. Morgan</em> court decision) is the first example provided of a pivotal event in the Latino rights movement; rather, it&rsquo;s a second example. Choice B is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to join two main clauses. Choice C is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to join two main clauses. Moreover, it fails to use appropriate punctuation to separate the supplementary element "for one" from the preceding main clause.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"5670a657","external_id":"86d7d04f-3f8f-48a2-8086-f4465af48abb","vaultid":null,"uId":"7d67ccef-a5b1-4965-ad08-8763ab2a9ed9","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>During the decades-long movement to codify the rights of Latinos in the US, certain events were pivotal: the founding of social justice group the League of United Latin American Citizens in <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> <em>Katzenbach <span data-ssml-sub-alias=\"v\">v.</span> Morgan</em> court decision in <span data-ssml-say-as=\"date\">1966</span>, which affirmed the rights of Latino voters, is another such event.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"cc32da26-85bd-476a-b105-f88fd0bf5edb","content":"<p><span data-ssml-say-as=\"date\">1929</span><span data-ssml-say-as=\"characters\">.</span> For one<span data-ssml-say-as=\"characters\">,</span> the</p>"},{"id":"1e705568-c0a3-4cb7-94a0-d9b555c57c72","content":"<p><span data-ssml-say-as=\"date\">1929</span><span data-ssml-say-as=\"characters\">,</span> for one<span data-ssml-say-as=\"characters\">,</span> the</p>"},{"id":"ffdd0cc6-df04-43d1-bffb-cefd7586a06f","content":"<p><span data-ssml-say-as=\"date\">1929</span> for one<span data-ssml-say-as=\"characters\">,</span> the</p>"},{"id":"47e4e962-4699-4dec-b6de-83961f2a963d","content":"<p><span data-ssml-say-as=\"date\">1929</span><span data-ssml-say-as=\"characters\">,</span> for one<span data-ssml-say-as=\"characters\">.</span> The</p>"}],"keys":["47e4e962-4699-4dec-b6de-83961f2a963d"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The conventions being tested are punctuation use between sentences and the punctuation of a supplementary element. This choice correctly uses a period to mark the boundary between one sentence (\"During...one\") and another (\"The <em>Katzenbach</em>...event\") and uses a comma to separate the supplementary phrase \"for one\" from the preceding main clause. Further, placing the period after \"for one\" correctly indicates that the information in the preceding main clause (\"the founding...1929\") is the first example provided of a pivotal event in the Latino rights movement.</p><p>Choice A is incorrect because placing the period after \"1929\" illogically indicates that the information in the next main clause (describing the <em>Katzenbach v. Morgan</em> court decision) is the first example provided of a pivotal event in the Latino rights movement; rather, it&rsquo;s a second example. Choice B is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to join two main clauses. Choice C is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to join two main clauses. Moreover, it fails to use appropriate punctuation to separate the supplementary element \"for one\" from the preceding main clause.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061189,"updateDate":1755117061189}$SATQ$::jsonb, 1755117061189, 1755117061189),
    ($SATQ$56770dda$SATQ$, $SATQ$90e6dd39-e06a-4cdd-8b24-75f1084a3f5d$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>In his 1963 exhibition <em>Exposition of Music&mdash;Electronic Television</em>, Korean American artist Nam June Paik showed how television images could be manipulated to express an artist&rsquo;s perspective. Today, Paik <span aria-hidden="true">______</span><span class="sr-only">blank</span> considered the first video artist.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"9ee541ae-83f5-4ee2-8a7a-4a405a1ede1b","content":"<p>will be</p>"},{"id":"b8068937-f6ad-4949-8443-04abab59f094","content":"<p>had been</p>"},{"id":"bf39024b-3012-4314-8bff-df4c730a50c0","content":"<p>was</p>"},{"id":"05b748be-6933-4917-87ee-1fa6d13cfc1a","content":"<p>is</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["05b748be-6933-4917-87ee-1fa6d13cfc1a"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is the use of verbs to express tense. In this choice, the present tense verb "is," used in conjunction with the word "today," correctly indicates that Paik is currently considered the first video artist.</p><p>Choice A is incorrect because the future tense verb "will be" doesn&rsquo;t indicate that Paik is currently considered the first video artist. Choice B is incorrect because the past perfect tense verb "had been" doesn&rsquo;t indicate that Paik is currently considered the first video artist. Choice C is incorrect because the past tense verb "was" doesn&rsquo;t indicate that Paik is currently considered the first video artist.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"56770dda","external_id":"90e6dd39-e06a-4cdd-8b24-75f1084a3f5d","vaultid":null,"uId":"d7e9c7af-3b2c-4c12-8a24-6bad78ebe4dc","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>In his 1963 exhibition <em>Exposition of Music&mdash;Electronic Television</em>, Korean American artist Nam June Paik showed how television images could be manipulated to express an artist&rsquo;s perspective. Today, Paik <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> considered the first video artist.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"9ee541ae-83f5-4ee2-8a7a-4a405a1ede1b","content":"<p>will be</p>"},{"id":"b8068937-f6ad-4949-8443-04abab59f094","content":"<p>had been</p>"},{"id":"bf39024b-3012-4314-8bff-df4c730a50c0","content":"<p>was</p>"},{"id":"05b748be-6933-4917-87ee-1fa6d13cfc1a","content":"<p>is</p>"}],"keys":["05b748be-6933-4917-87ee-1fa6d13cfc1a"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is the use of verbs to express tense. In this choice, the present tense verb \"is,\" used in conjunction with the word \"today,\" correctly indicates that Paik is currently considered the first video artist.</p><p>Choice A is incorrect because the future tense verb \"will be\" doesn&rsquo;t indicate that Paik is currently considered the first video artist. Choice B is incorrect because the past perfect tense verb \"had been\" doesn&rsquo;t indicate that Paik is currently considered the first video artist. Choice C is incorrect because the past tense verb \"was\" doesn&rsquo;t indicate that Paik is currently considered the first video artist.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1691007959348,"updateDate":1691007959348}$SATQ$::jsonb, 1691007959348, 1691007959348),
    ($SATQ$576b2c70$SATQ$, $SATQ$d89bd0e9-6f42-40c3-823a-8b84df10b1dd$SATQ$::uuid, $SATQ$f10f8955-ebee-490a-bab6-bdbc9ec520cd$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>A member of the Cherokee Nation, Mary Golda Ross is renowned for her contributions to NASA&rsquo;s Planetary Flight Handbook, which <span aria-hidden="true">______</span><span class="sr-only">blank</span> detailed mathematical guidance for missions to Mars and Venus.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"1486a0ab-4b20-47c0-a0c8-b3afcbfaa157","content":"<p>provided</p>"},{"id":"1a412e9b-98f3-4a6b-af02-3148e94709cf","content":"<p>having provided</p>"},{"id":"f42c83dc-4715-408b-93d6-55a7718dce7f","content":"<p>to provide</p>"},{"id":"5f0cc8cf-e567-4165-8ae2-d76fc4f38d5e","content":"<p>providing</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["1486a0ab-4b20-47c0-a0c8-b3afcbfaa157"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the use of finite verbs in a relative clause. Relative clauses, such as the one beginning with &ldquo;which,&rdquo; require a finite verb, a verb that can function as the main verb of a clause. This choice correctly supplies the clause with the finite past tense verb &ldquo;provided.&rdquo; </p><p>Choice B is incorrect because the non-finite participle &ldquo;having provided&rdquo; doesn&rsquo;t supply the clause with a finite verb. Choice C is incorrect because the non-finite to-infinitive &ldquo;to provide&rdquo; doesn&rsquo;t supply the clause with a finite verb. Choice D is incorrect because the non-finite participle &ldquo;providing&rdquo; doesn&rsquo;t supply the clause with a finite verb. </p>$SATQ$, false, 0, $SATQ$OSP-629-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$2ddf83d9-331f-4e0f-9ff6-6c768279dd3a$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"576b2c70","external_id":"d89bd0e9-6f42-40c3-823a-8b84df10b1dd","vaultid":"f10f8955-ebee-490a-bab6-bdbc9ec520cd","uId":"dd91cea3-86d6-4541-8db3-3ff5ab8b59ca","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>A member of the Cherokee Nation, Mary Golda Ross is renowned for her contributions to NASA&rsquo;s Planetary Flight Handbook, which <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> detailed mathematical guidance for missions to Mars and Venus.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"1486a0ab-4b20-47c0-a0c8-b3afcbfaa157","content":"<p>provided</p>"},{"id":"1a412e9b-98f3-4a6b-af02-3148e94709cf","content":"<p>having provided</p>"},{"id":"f42c83dc-4715-408b-93d6-55a7718dce7f","content":"<p>to provide</p>"},{"id":"5f0cc8cf-e567-4165-8ae2-d76fc4f38d5e","content":"<p>providing</p>"}],"keys":["1486a0ab-4b20-47c0-a0c8-b3afcbfaa157"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is the use of finite verbs in a relative clause. Relative clauses, such as the one beginning with &ldquo;which,&rdquo; require a finite verb, a verb that can function as the main verb of a clause. This choice correctly supplies the clause with the finite past tense verb &ldquo;provided.&rdquo; </p><p>Choice B is incorrect because the non-finite participle &ldquo;having provided&rdquo; doesn&rsquo;t supply the clause with a finite verb. Choice C is incorrect because the non-finite to-infinitive &ldquo;to provide&rdquo; doesn&rsquo;t supply the clause with a finite verb. Choice D is incorrect because the non-finite participle &ldquo;providing&rdquo; doesn&rsquo;t supply the clause with a finite verb. </p>","parenttemplatename":"OSP-629-SEC","parenttemplateid":"","templateclusterid":"2ddf83d9-331f-4e0f-9ff6-6c768279dd3a","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959340,"updateDate":1691007959340}$SATQ$::jsonb, 1691007959340, 1691007959340),
    ($SATQ$577b09fa$SATQ$, $SATQ$12a5beb4-702a-42ed-b6ee-f189a7ea04e6$SATQ$::uuid, $SATQ$23a0b771-704a-46de-93fb-b1aeba271513$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Robin Wall Kimmerer of the Citizen Potawatomi Nation is a bryologist, a plant scientist who specializes in mosses. To Kimmerer, mosses are Earth&rsquo;s most adaptable plants: they can clone <span aria-hidden="true">______</span><span class="sr-only">blank</span> enter a dormant state in times of drought, and grow in areas that don&rsquo;t have soil.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"7f68e597-88ee-4ba9-9a7a-63cc647137d4","content":"<p>themselves;</p>"},{"id":"ed33112e-b7f1-4613-8e01-b87fe3c53d5a","content":"<p>themselves,</p>"},{"id":"eb3104e0-11bd-4461-9f96-90e9eea8eb02","content":"<p>themselves. And</p>"},{"id":"ca8d8393-7cdf-4be5-af87-7fdb0e770198","content":"<p>themselves</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["ed33112e-b7f1-4613-8e01-b87fe3c53d5a"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is the punctuation of items in a series. The comma after &ldquo;themselves&rdquo; is used conventionally to separate the first item (&ldquo;they can clone themselves&rdquo;) and the second item (&ldquo;enter a dormant state in times of drought&rdquo;) in the series of things mosses can do.&nbsp;</p><p>Choice A is incorrect because a semicolon can&rsquo;t be used in this way to separate items in a simple series such as this. Choice C is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with &ldquo;And enter.&rdquo; Choice D is incorrect because it fails to use appropriate punctuation to separate the first and second items in the series. </p>$SATQ$, false, 0, $SATQ$OSP-777-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$afc3559d-3a7f-41c0-9a6e-51ad94e8ec3b$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"577b09fa","external_id":"12a5beb4-702a-42ed-b6ee-f189a7ea04e6","vaultid":"23a0b771-704a-46de-93fb-b1aeba271513","uId":"85e94d02-a7fd-41b6-bf14-1d7826272883","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Robin Wall Kimmerer of the Citizen Potawatomi Nation is a bryologist, a plant scientist who specializes in mosses. To Kimmerer, mosses are Earth&rsquo;s most adaptable plants: they can clone <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> enter a dormant state in times of drought, and grow in areas that don&rsquo;t have soil.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"7f68e597-88ee-4ba9-9a7a-63cc647137d4","content":"<p>themselves;</p>"},{"id":"ed33112e-b7f1-4613-8e01-b87fe3c53d5a","content":"<p>themselves,</p>"},{"id":"eb3104e0-11bd-4461-9f96-90e9eea8eb02","content":"<p>themselves. And</p>"},{"id":"ca8d8393-7cdf-4be5-af87-7fdb0e770198","content":"<p>themselves</p>"}],"keys":["ed33112e-b7f1-4613-8e01-b87fe3c53d5a"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is the punctuation of items in a series. The comma after &ldquo;themselves&rdquo; is used conventionally to separate the first item (&ldquo;they can clone themselves&rdquo;) and the second item (&ldquo;enter a dormant state in times of drought&rdquo;) in the series of things mosses can do.&nbsp;</p><p>Choice A is incorrect because a semicolon can&rsquo;t be used in this way to separate items in a simple series such as this. Choice C is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with &ldquo;And enter.&rdquo; Choice D is incorrect because it fails to use appropriate punctuation to separate the first and second items in the series. </p>","parenttemplatename":"OSP-777-SEC","parenttemplateid":"","templateclusterid":"afc3559d-3a7f-41c0-9a6e-51ad94e8ec3b","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959352,"updateDate":1691007959352}$SATQ$::jsonb, 1691007959352, 1691007959352),
    ($SATQ$57998dd3$SATQ$, $SATQ$461da84a-fab3-40aa-ac49-bb682b69b95e$SATQ$::uuid, $SATQ$2fa50d88-e5ea-4283-b3fc-ef929f2cfea1$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>Obsidian is a kind of volcanic glass formed when lava cools so quickly that the atoms inside it cannot arrange themselves in a crystalline structure. You <span aria-hidden="true">______</span><span class="sr-only">blank</span> more about obsidian&rsquo;s structure, which is classified as amorphous, in a later chapter.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"b1de9794-79b2-4969-93ec-e94a28c2e909","content":"<p>had learned</p>"},{"id":"4bb5c9bb-0364-44e9-a801-ab45dedb97aa","content":"<p>had been learning</p>"},{"id":"0cf30e9b-6da6-40bf-b3f5-5f24011c92d0","content":"<p>will learn</p>"},{"id":"03673a13-e9f5-4613-ab57-e8353ac286c8","content":"<p>have learned</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["0cf30e9b-6da6-40bf-b3f5-5f24011c92d0"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is the use of verbs to express tense in a sentence. In this choice, the future tense verb &ldquo;will learn,&rdquo; used in conjunction with the phrase &ldquo;in a later chapter,&rdquo; correctly indicates that &ldquo;you&rdquo; (the reader) are going to learn about obsidian&rsquo;s structure at some point in the future. </p><p>Choice A is incorrect because the past perfect verb &ldquo;had learned&rdquo; doesn&rsquo;t indicate that the subject is going to learn about obsidian&rsquo;s structure in the future. Choice B is incorrect because the past perfect progressive verb &ldquo;had been learning&rdquo; doesn&rsquo;t indicate that the subject is going to learn about obsidian&rsquo;s structure in the future. Choice D is incorrect because the present perfect verb &ldquo;have learned&rdquo; doesn&rsquo;t indicate that the subject is going to learn about obsidian&rsquo;s structure in the future. </p>$SATQ$, false, 0, $SATQ$OSP-748-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$55f93536-b3a0-46ea-a749-b054bdfc5e8d$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"57998dd3","external_id":"461da84a-fab3-40aa-ac49-bb682b69b95e","vaultid":"2fa50d88-e5ea-4283-b3fc-ef929f2cfea1","uId":"2de472d2-a02a-4a7d-bd9a-2b9f566bed17","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>Obsidian is a kind of volcanic glass formed when lava cools so quickly that the atoms inside it cannot arrange themselves in a crystalline structure. You <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> more about obsidian&rsquo;s structure, which is classified as amorphous, in a later chapter.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"b1de9794-79b2-4969-93ec-e94a28c2e909","content":"<p>had learned</p>"},{"id":"4bb5c9bb-0364-44e9-a801-ab45dedb97aa","content":"<p>had been learning</p>"},{"id":"0cf30e9b-6da6-40bf-b3f5-5f24011c92d0","content":"<p>will learn</p>"},{"id":"03673a13-e9f5-4613-ab57-e8353ac286c8","content":"<p>have learned</p>"}],"keys":["0cf30e9b-6da6-40bf-b3f5-5f24011c92d0"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is the use of verbs to express tense in a sentence. In this choice, the future tense verb &ldquo;will learn,&rdquo; used in conjunction with the phrase &ldquo;in a later chapter,&rdquo; correctly indicates that &ldquo;you&rdquo; (the reader) are going to learn about obsidian&rsquo;s structure at some point in the future. </p><p>Choice A is incorrect because the past perfect verb &ldquo;had learned&rdquo; doesn&rsquo;t indicate that the subject is going to learn about obsidian&rsquo;s structure in the future. Choice B is incorrect because the past perfect progressive verb &ldquo;had been learning&rdquo; doesn&rsquo;t indicate that the subject is going to learn about obsidian&rsquo;s structure in the future. Choice D is incorrect because the present perfect verb &ldquo;have learned&rdquo; doesn&rsquo;t indicate that the subject is going to learn about obsidian&rsquo;s structure in the future. </p>","parenttemplatename":"OSP-748-SEC","parenttemplateid":"","templateclusterid":"55f93536-b3a0-46ea-a749-b054bdfc5e8d","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959350,"updateDate":1691007959350}$SATQ$::jsonb, 1691007959350, 1691007959350),
    ($SATQ$588887b9$SATQ$, $SATQ$58ceaace-6b30-4c79-a30a-16ae42c6a122$SATQ$::uuid, $SATQ$03cc3079-64b6-429a-a434-150466600486$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>In 1881, French chemist Camille Faure redesigned the rechargeable lead-acid battery. Faure&rsquo;s design greatly increased the amount of electricity that the original battery, which the French physicist Gaston Plant&eacute; <span aria-hidden="true">______</span><span class="sr-only">blank</span> fifteen years earlier, could hold.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"3c6a793d-1799-4c53-bd45-536fa6617486","content":"<p>is inventing</p>"},{"id":"804bbbad-abeb-430d-88c6-7acb1de317b5","content":"<p>will invent</p>"},{"id":"65d9b28f-a632-47e9-9284-afc3ae479f13","content":"<p>invents</p>"},{"id":"30fd212e-b928-4bed-9416-4f768c4cd88e","content":"<p>had invented</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["30fd212e-b928-4bed-9416-4f768c4cd88e"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. Faure redesigned the battery in 1881, and the original battery was invented &ldquo;fifteen years earlier.&rdquo; Notice that this is the only choice in the past tense. To indicate that a past occurrence took place before another past occurrence, we need to use &ldquo;had&rdquo; + the past tense form of the verb. This is called the &ldquo;past perfect&rdquo; tense. </p><p>Choice A is incorrect. This choice creates a tense error. Plant&eacute; invented the original battery in the past, so we shouldn&rsquo;t use the present tense &ldquo;is inventing.&rdquo; Choice B is incorrect. This choice creates a tense error. Plant&eacute; invented the original battery in the past, so we shouldn&rsquo;t use the future tense &ldquo;will invent.&rdquo; Choice C is incorrect. This choice creates a tense error. Plant&eacute; invented the original battery in the past, so we shouldn&rsquo;t use the present tense &ldquo;invents.&rdquo; </p>$SATQ$, false, 0, $SATQ$OSP-KA-FSS-E003$SATQ$, $SATQ$$SATQ$, $SATQ$c832d63b-65c7-470a-9aa9-055b87e6942f$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"588887b9","external_id":"58ceaace-6b30-4c79-a30a-16ae42c6a122","vaultid":"03cc3079-64b6-429a-a434-150466600486","uId":"eb0843fa-d56e-4acd-98ac-f20cf56245ed","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>In 1881, French chemist Camille Faure redesigned the rechargeable lead-acid battery. Faure&rsquo;s design greatly increased the amount of electricity that the original battery, which the French physicist Gaston Plant&eacute; <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> fifteen years earlier, could hold.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"3c6a793d-1799-4c53-bd45-536fa6617486","content":"<p>is inventing</p>"},{"id":"804bbbad-abeb-430d-88c6-7acb1de317b5","content":"<p>will invent</p>"},{"id":"65d9b28f-a632-47e9-9284-afc3ae479f13","content":"<p>invents</p>"},{"id":"30fd212e-b928-4bed-9416-4f768c4cd88e","content":"<p>had invented</p>"}],"keys":["30fd212e-b928-4bed-9416-4f768c4cd88e"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. Faure redesigned the battery in 1881, and the original battery was invented &ldquo;fifteen years earlier.&rdquo; Notice that this is the only choice in the past tense. To indicate that a past occurrence took place before another past occurrence, we need to use &ldquo;had&rdquo; + the past tense form of the verb. This is called the &ldquo;past perfect&rdquo; tense. </p><p>Choice A is incorrect. This choice creates a tense error. Plant&eacute; invented the original battery in the past, so we shouldn&rsquo;t use the present tense &ldquo;is inventing.&rdquo; Choice B is incorrect. This choice creates a tense error. Plant&eacute; invented the original battery in the past, so we shouldn&rsquo;t use the future tense &ldquo;will invent.&rdquo; Choice C is incorrect. This choice creates a tense error. Plant&eacute; invented the original battery in the past, so we shouldn&rsquo;t use the present tense &ldquo;invents.&rdquo; </p>","parenttemplatename":"OSP-KA-FSS-E003","parenttemplateid":"","templateclusterid":"c832d63b-65c7-470a-9aa9-055b87e6942f","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959366,"updateDate":1691007959366}$SATQ$::jsonb, 1691007959366, 1691007959366),
    ($SATQ$59094d87$SATQ$, $SATQ$e0ef59fa-d068-4fe0-a711-c0cfe98b9185$SATQ$::uuid, $SATQ$a186419c-3f4f-406b-86a2-e58015217cdd$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>The Tantaquidgeon Museum in Uncasville, Connecticut, was founded in 1931 with the goal of showcasing the culture and history of the Mohegan <span aria-hidden="true">______</span><span class="sr-only">blank</span> today, nearly a century later, it is the oldest Native-owned and -operated museum in the country.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"6e06d1a8-320c-4255-b4b1-d24b48131928","content":"<p>Tribe, and</p>"},{"id":"55cce040-ee90-4c8a-bb5f-51a361a1bda0","content":"<p>Tribe</p>"},{"id":"1dc299e0-4433-4e3e-ab47-e46c67d8c0d2","content":"<p>Tribe and</p>"},{"id":"3078af1f-2b36-4c71-88ff-1e39abeb29fd","content":"<p>Tribe,</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["6e06d1a8-320c-4255-b4b1-d24b48131928"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. This choice uses a comma and a coordinating conjunction (&ldquo;and&rdquo;) to join two independent clauses (&ldquo;The Tantaquidgeon&hellip;Tribe&rdquo; and &ldquo;Today&hellip;country&rdquo;). </p><p>Choice B is incorrect. This choice results in a grammar error known as a run-on sentence. The clauses before and after &ldquo;Tribe&rdquo; are both independent, so they need to be separated with some sort of punctuation. Choice C is incorrect. This choice results in a grammar error known as a run-on sentence. The clauses before and after &ldquo;and&rdquo; are both independent, so they can&rsquo;t be linked with just a conjunction. A comma would also be required. Choice D is incorrect. This choice results in a grammar error called a comma splice. The clauses before and after &ldquo;Tribe&rdquo; are both independent, so they can&rsquo;t be linked with just a comma. A coordinating conjunction like &ldquo;and&rdquo; or &ldquo;but&rdquo; would also be required. </p>$SATQ$, false, 0, $SATQ$OSP-KA-BOU-H007$SATQ$, $SATQ$$SATQ$, $SATQ$857dd99c-93ef-4f3a-9a15-ee8e193f2d9f$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"59094d87","external_id":"e0ef59fa-d068-4fe0-a711-c0cfe98b9185","vaultid":"a186419c-3f4f-406b-86a2-e58015217cdd","uId":"8604696d-367a-427f-992e-c5e624f22ec1","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>The Tantaquidgeon Museum in Uncasville, Connecticut, was founded in 1931 with the goal of showcasing the culture and history of the Mohegan <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> today, nearly a century later, it is the oldest Native-owned and -operated museum in the country.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"6e06d1a8-320c-4255-b4b1-d24b48131928","content":"<p>Tribe, and</p>"},{"id":"55cce040-ee90-4c8a-bb5f-51a361a1bda0","content":"<p>Tribe</p>"},{"id":"1dc299e0-4433-4e3e-ab47-e46c67d8c0d2","content":"<p>Tribe and</p>"},{"id":"3078af1f-2b36-4c71-88ff-1e39abeb29fd","content":"<p>Tribe,</p>"}],"keys":["6e06d1a8-320c-4255-b4b1-d24b48131928"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. This choice uses a comma and a coordinating conjunction (&ldquo;and&rdquo;) to join two independent clauses (&ldquo;The Tantaquidgeon&hellip;Tribe&rdquo; and &ldquo;Today&hellip;country&rdquo;). </p><p>Choice B is incorrect. This choice results in a grammar error known as a run-on sentence. The clauses before and after &ldquo;Tribe&rdquo; are both independent, so they need to be separated with some sort of punctuation. Choice C is incorrect. This choice results in a grammar error known as a run-on sentence. The clauses before and after &ldquo;and&rdquo; are both independent, so they can&rsquo;t be linked with just a conjunction. A comma would also be required. Choice D is incorrect. This choice results in a grammar error called a comma splice. The clauses before and after &ldquo;Tribe&rdquo; are both independent, so they can&rsquo;t be linked with just a comma. A coordinating conjunction like &ldquo;and&rdquo; or &ldquo;but&rdquo; would also be required. </p>","parenttemplatename":"OSP-KA-BOU-H007","parenttemplateid":"","templateclusterid":"857dd99c-93ef-4f3a-9a15-ee8e193f2d9f","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959359,"updateDate":1691007959359}$SATQ$::jsonb, 1691007959359, 1691007959359),
    ($SATQ$59209b6d$SATQ$, $SATQ$7ec16da8-46a0-483b-91a8-51977dd43623$SATQ$::uuid, $SATQ$30517ad5-084a-4f6b-9f31-cb95f883d896$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Based on genetic evidence, archaeologists have generally agreed that reindeer domestication began in the eleventh century CE. However, since uncovering fragments of a 2,000-year-old reindeer training harness in northern Siberia, <span aria-hidden="true">______</span><span class="sr-only">blank</span> may have begun much earlier.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"c8c90893-5bf0-47a3-bfe1-242c40a191a0","content":"<p>researcher Robert Losey has argued that domestication&nbsp;</p>"},{"id":"06e33d84-25a8-40c5-b200-21aa592f1725","content":"<p>researcher Robert Losey&rsquo;s argument is that domestication</p>"},{"id":"23481b5b-046e-46ab-ab10-d356f8327e67","content":"<p>domestication, researcher Robert Losey has argued,</p>"},{"id":"d9bf33f2-414f-431e-8ad9-3e8e700da63a","content":"<p>the argument researcher Robert Losey has made is that domestication</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["c8c90893-5bf0-47a3-bfe1-242c40a191a0"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is subject-modifier placement. This choice makes the noun phrase &ldquo;researcher Robert Losey&rdquo; the subject of the sentence and places it immediately after the modifying phrase &ldquo;since&hellip;Siberia.&rdquo; In doing so, this choice clearly establishes that researcher Robert Losey&mdash;and not another noun in the sentence&mdash;is who uncovered fragments of a 2,000-year-old reindeer training harness in northern Siberia. </p><p>Choice B is incorrect because it results in a dangling modifier. The placement of the noun phrase &ldquo;researcher Robert Losey&rsquo;s argument&rdquo; immediately after the modifying phrase illogically suggests that the &ldquo;argument&rdquo; is what uncovered fragments of a 2,000-year-old reindeer training harness in northern Siberia. Choice C is incorrect because it results in a dangling modifier. The placement of the noun &ldquo;domestication&rdquo; immediately after the modifying phrase illogically suggests that &ldquo;domestication&rdquo; is what uncovered fragments of a 2,000-year-old reindeer training harness in northern Siberia. Choice D is incorrect because it results in a dangling modifier. The placement of the noun phrase &ldquo;the argument&rdquo; immediately after the modifying phrase illogically suggests that the &ldquo;argument&rdquo; is what uncovered fragments of a 2,000-year-old reindeer training harness in northern Siberia. </p>$SATQ$, false, 0, $SATQ$OSP-665-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$1b516901-e2ea-4d56-907b-41b429c27437$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"59209b6d","external_id":"7ec16da8-46a0-483b-91a8-51977dd43623","vaultid":"30517ad5-084a-4f6b-9f31-cb95f883d896","uId":"5b38fcc4-e8ad-4026-bbef-2d1a2379da7c","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Based on genetic evidence, archaeologists have generally agreed that reindeer domestication began in the eleventh century CE. However, since uncovering fragments of a 2,000-year-old reindeer training harness in northern Siberia, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> may have begun much earlier.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id"